# Search accessibility tree for file-related elements
tree = cdp('Accessibility.getFullAXTree')['nodes']
file_elements = []
for node in tree:
    name_val = node.get('name', {}).get('value', '')
    role_val = node.get('role', {}).get('value', '')
    if 'file' in name_val.lower() or 'upload' in name_val.lower() or role_val == 'input file':
        file_elements.append({
            'nodeId': node['nodeId'],
            'backendDOMNodeId': node.get('backendDOMNodeId'),
            'name': name_val,
            'role': role_val
        })

print(f"Found {len(file_elements)} file-related elements")
for fe in file_elements[:5]:
    print(fe)

